package ama.config.json;
import ama.model.*;import org.junit.jupiter.api.Test;import java.net.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class Task09OutputAdmissionTest extends Task09ControlledClientTest {
 @Test void originalWireBudgetRejectsDurableSuccessBeforeResultGet()throws Exception{
  var wire=Task09ControlledProtocolTest.wire();var json=new com.fasterxml.jackson.databind.ObjectMapper();var request=json.readTree(wire.body());var gets=new java.util.concurrent.atomic.AtomicInteger();var server=com.sun.net.httpserver.HttpServer.create(new InetSocketAddress("127.0.0.1",0),1);server.createContext("/v1/minutes/",exchange->{try{byte[] bytes;if(exchange.getRequestURI().getPath().startsWith("/v1/minutes/results/")){gets.incrementAndGet();bytes="0123456789".getBytes(java.nio.charset.StandardCharsets.US_ASCII);}else{exchange.getRequestBody().readNBytes(16777217);var out=json.createObjectNode();for(String key:List.of("protocolVersion","executionId","executionNo","logicalBusinessKey","logicalRequestHash","executionRequestHash","payloadSha256"))out.set(key,request.get(key));out.put("state","SUCCEEDED");out.put("resultId","cmr-00000000-0000-4000-8000-000000000001");out.put("outputSha256","0".repeat(64));out.put("outputBytes",10);bytes=json.writeValueAsBytes(out);}exchange.getResponseHeaders().set("Content-Type","application/json");exchange.getResponseHeaders().set("Connection","close");exchange.sendResponseHeaders(200,bytes.length);exchange.getResponseBody().write(bytes);}finally{exchange.close();}});server.start();
  try(var c=(ControlledMinutesClient)client(server.getAddress().getPort())){var method=assertDoesNotThrow(()->c.getClass().getMethod("prepare",byte[].class,String.class,long.class));var bounded=(ControlledMinutesClient.Request)method.invoke(c,wire.body(),wire.header(),1L);var result=c.execute(bounded,OPEN);assertEquals("SUCCEEDED",result.state());assertNull(result.output());assertEquals(true,result.getClass().getMethod("outputBudgetExceeded").invoke(result));assertEquals(0,gets.get());}finally{server.stop(0);}
 }
}
